func TestGetDerivedPubKeyRejectsInvalidInput(t *testing.T) {
	tests := map[string]struct{ pubKey, chainCode, path string }{
		"short chain code":   {testECDSAPublicKey, testHexChainCode[:62], "m/0"},
		"bad chain code hex": {testECDSAPublicKey, "zz" + testHexChainCode[2:], "m/0"},
		"bad path":           {testECDSAPublicKey, testHexChainCode, "m/44'/x/0"},
		"index overflow":     {testECDSAPublicKey, testHexChainCode, "m/4294967296"},
		"hardened index":     {testECDSAPublicKey, testHexChainCode, "m/2147483648"},
		"EdDSA key":          {testEdDSAPublicKey, testHexChainCode, "m/0"},
	}
	for name, tt := range tests {
		t.Run(name, func(t *testing.T) {
			_, err := getDerivedPubKey(tt.pubKey, tt.chainCode, tt.path)
			assert.Error(t, err)
		})
	}
}
